/bin/bash -lc "python - <<'PY'
import socket,urllib.request
for host in ['api.assemblyai.com','streaming.assemblyai.com','www.assemblyai.com','pypi.org']:
 print(host,socket.gethostbyname_ex(host))
 try:
  r=urllib.request.urlopen('https://'+host,timeout=10);print(r.status,r.read(150))
 except Exception as e:print(type(e).__name__,str(e))
PY"

