/bin/bash -lc "python -m pip install 'websockets>=15,<16' && python - <<'PY'
import urllib.request
urls=['https://assemblyai.com/docs/speech-to-text/universal-streaming','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/streaming/v3/models.py','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/streaming/v3/client.py']
for i,u in enumerate(urls):
 try:
  d=urllib.request.urlopen(u,timeout=15).read().decode();open('/tmp/aai-'+str(i),'w').write(d);print(i,len(d),d[:200])
 except Exception as e: print(i,e)
PY"

